        let raw = Value::F64(cv.as_num());
        if let Some(x) = conv_expr::eval_with("Image::ExifTool::Exif::PrintExposureTime($val)", &cv, &ctx) { cv = x; }
        tags.push(mk("ExposureTime", 0x36, cv.as_string(), raw, GRP0, GRP1, GRP2, PRIO));
